import{_ as l,H as t,f as i,i as n}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"阶段作业｜让你的 Agent 学会“慢思考 + 动手做事”","description":"","frontmatter":{},"headers":[{"level":2,"title":"🎯 作业目标（当前阶段）","slug":"🎯-作业目标-当前阶段","link":"#🎯-作业目标-当前阶段","children":[{"level":3,"title":"🟢 Level 1（目前可以完成｜基于前6讲）","slug":"🟢-level-1-目前可以完成-基于前6讲","link":"#🟢-level-1-目前可以完成-基于前6讲","children":[]},{"level":3,"title":"🟡 Level 2（进阶｜可提前探索）","slug":"🟡-level-2-进阶-可提前探索","link":"#🟡-level-2-进阶-可提前探索","children":[]},{"level":3,"title":"🔴 Level 3（挑战｜对标业界Claude Code最佳实践）","slug":"🔴-level-3-挑战-对标业界claude-code最佳实践","link":"#🔴-level-3-挑战-对标业界claude-code最佳实践","children":[]}]},{"level":2,"title":"📦 如何 提交 & 提交内容与格式","slug":"📦-如何-提交-提交内容与格式","link":"#📦-如何-提交-提交内容与格式","children":[]},{"level":2,"title":"🧪 我们会重点关注什么？（评分标准）","slug":"🧪-我们会重点关注什么-评分标准","link":"#🧪-我们会重点关注什么-评分标准","children":[]}],"relativePath":"从0开始构建AgentHarness/阶段作业｜让你的Agent学会“慢思考+动手做事”.md","filePath":"从0开始构建AgentHarness/阶段作业｜让你的Agent学会“慢思考+动手做事”.md","lastUpdated":1779818543000}'),r={name:"从0开始构建AgentHarness/阶段作业｜让你的Agent学会“慢思考+动手做事”.md"};function o(p,e,a,s,g,d){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="阶段作业-让你的-agent-学会-慢思考-动手做事" tabindex="-1">阶段作业｜让你的 Agent 学会“慢思考 + 动手做事” <a class="header-anchor" href="#阶段作业-让你的-agent-学会-慢思考-动手做事" aria-label="Permalink to &quot;阶段作业｜让你的 Agent 学会“慢思考 + 动手做事”&quot;">​</a></h1><p>课程更新到第 06 讲，我们已经一起完成了：</p><ul><li>Main Loop（Agent 如何持续运行）</li><li>慢思考（Thinking 阶段拆分）</li><li>Provider 抽象（接入大模型）</li><li>Tool Registry（工具注册与分发）</li><li>YOLO 工具哲学（用最少工具完成最多事情）</li></ul><p>接下来，是时候把这些能力“合起来用一次”了👇</p><h2 id="🎯-作业目标-当前阶段" tabindex="-1">🎯 <strong>作业目标（当前阶段）</strong> <a class="header-anchor" href="#🎯-作业目标-当前阶段" aria-label="Permalink to &quot;🎯 **作业目标（当前阶段）**&quot;">​</a></h2><p>基于你已有的 Agent Harness，实现一个：</p><p>👉 <strong>“能慢思考、会用工具、能推进任务”的 Agent</strong></p><hr><h3 id="🟢-level-1-目前可以完成-基于前6讲" tabindex="-1">🟢 <strong>Level 1（目前可以完成｜基于前6讲）</strong> <a class="header-anchor" href="#🟢-level-1-目前可以完成-基于前6讲" aria-label="Permalink to &quot;🟢 **Level 1（目前可以完成｜基于前6讲）**&quot;">​</a></h3><p>让你的 Agent具备以下能力：</p><p>1️⃣ <strong>慢思考（Thinking 阶段）</strong></p><ul><li><p>在 Main Loop 中，显式区分 Thinking / Acting</p></li><li><p>先思考“下一步做什么”，再执行</p></li></ul><p>2️⃣ <strong>工具调用（Tool Registry）</strong></p><ul><li><p>至少接入 1 个工具（如：文件读取 / 简单编辑）</p></li><li><p>通过统一注册与分发机制调用（而不是写死）</p></li></ul><p>3️⃣ <strong>YOLO 执行一次完整任务</strong></p><ul><li><p>给定一个目标（如：读取一个文件并总结）</p></li><li><p>Agent 自己决定调用工具并完成任务</p></li></ul><p>👉 关键词： <strong>慢思考 → 动手做 → 得到结果</strong></p><hr><h3 id="🟡-level-2-进阶-可提前探索" tabindex="-1">🟡 <strong>Level 2（进阶｜可提前探索）</strong> <a class="header-anchor" href="#🟡-level-2-进阶-可提前探索" aria-label="Permalink to &quot;🟡 **Level 2（进阶｜可提前探索）**&quot;">​</a></h3><p>在 Level 1 基础上尝试：</p><ul><li><p>让 Thinking 阶段更结构化（比如输出“计划”而不是一句话）</p></li><li><p>支持多步执行（一次任务不一定一步完成）</p></li><li><p>尝试让 Agent 根据情况选择不同工具（而不是固定一个）</p></li></ul><p>👉 关键词： <strong>让 Agent 开始“连续行动”</strong></p><hr><h3 id="🔴-level-3-挑战-对标业界claude-code最佳实践" tabindex="-1">🔴 <strong>Level 3（挑战｜对标业界Claude Code最佳实践）</strong> <a class="header-anchor" href="#🔴-level-3-挑战-对标业界claude-code最佳实践" aria-label="Permalink to &quot;🔴 **Level 3（挑战｜对标业界Claude Code最佳实践）**&quot;">​</a></h3><p>如果你有兴趣，可以结合 Claude Code 设计思路，尝试：</p><ul><li><p>做一个更清晰的循环：Thinking → Acting → Observation → 再思考</p></li><li><p>让 Agent 根据执行结果调整下一步行为</p></li><li><p>尝试优化 Prompt 结构（思考 vs 执行分离）</p></li></ul><p>👉 关键词： <strong>让 Agent 开始“像一个系统在运转”</strong></p><p><strong>Claude Code 源码泄漏存档：</strong> <a href="https://github.com/FlyAIBox/civil-engineering-cloud-claude-code-source-v2.1.88" target="_blank" rel="noreferrer">https://github.com/FlyAIBox/civil-engineering-cloud-claude-code-source-v2.1.88</a></p><hr><h2 id="📦-如何-提交-提交内容与格式" tabindex="-1">📦 如何 <strong>提交 &amp; 提交内容与格式</strong> <a class="header-anchor" href="#📦-如何-提交-提交内容与格式" aria-label="Permalink to &quot;📦 如何 **提交 &amp; 提交内容与格式**&quot;">​</a></h2><p>按以下结构提交到本讲留言区（缺一不可）：</p><p>1️⃣ <strong>代码仓库（必需）</strong></p><ul><li><p>提供 GitHub / Gitee 链接</p></li><li><p>至少包含：Main Loop、Thinking、Tool 调用核心代码</p></li></ul><p>2️⃣ <strong>运行演示（必需）</strong></p><ul><li><p>一段真实任务执行过程（建议贴日志）</p></li><li><p>示例格式：</p><ul><li><p>用户输入</p></li><li><p>Thinking 输出</p></li><li><p>Tool 调用</p></li><li><p>最终结果</p></li></ul></li></ul><p>3️⃣ <strong>设计说明（必需）</strong></p><p>请用 3～5 句话说明：</p><ul><li><p>你的 Main Loop 是怎么设计的？</p></li><li><p>Thinking 和 Acting 是如何拆分的？</p></li><li><p>Tool Registry 是如何组织的？</p></li></ul><p>👉 不要求长，但要讲“你的取舍”</p><hr><h2 id="🧪-我们会重点关注什么-评分标准" tabindex="-1">🧪 <strong>我们会重点关注什么？（评分标准）</strong> <a class="header-anchor" href="#🧪-我们会重点关注什么-评分标准" aria-label="Permalink to &quot;🧪 **我们会重点关注什么？（评分标准）**&quot;">​</a></h2><p>不是看“功能多不多”，而是看这 3 点：</p><p>✅ <strong>结构是否清晰</strong>（有没有真正拆出 Thinking）</p><p>✅ <strong>是否解耦</strong>（Tool 有没有通过 Registry 管理）</p><p>✅ <strong>是否可扩展</strong>（能不能自然加新工具 / 新步骤）</p><p>💬 <strong>加分项（可选）</strong></p><ul><li><p>有清晰的日志输出（能看到 Agent 的“思考过程”）</p></li><li><p>有失败案例（以及你是怎么修的）</p></li><li><p>有自己的小优化（哪怕很简单）</p></li></ul><p>📌 <strong>说明</strong></p><ul><li><p>不要求一步到位，可以随着课程进度不断升级</p></li><li><p>欢迎把你的执行过程（Thinking / Tool 调用 / 输出）贴出来</p></li><li><p>我们会挑选一些实现做点评（重点看“设计”，不只是结果）</p></li></ul><p><strong>课程结课后一周，我们会选择其中最佳的5个设计方案，给予奖励并在课程内公示。</strong></p><p>奖励：价值99元的课程阅码，现有课程任选</p><p>好记性不如烂笔头！如果你已经学完更新的内容，希望你可以好好完成以上作业， <strong>以输出倒逼输入</strong>，相信会有意想不到的收获～</p><p>也欢迎大家在评论区说说目前卡在哪一块，我们会优先在后面的内容里重点补上。</p><p>👉 <strong>好课推荐</strong>： <a href="http://gk.link/a/12IZI" target="_blank" rel="noreferrer">《AI原生开发工作流实战》</a> <strong>Tony Bai 出品，已完结</strong></p><p>——Claude Code + SDD，打造你的自动化 AI 工作流</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E6%9E%84%E5%BB%BAAgentHarness/images/972842/761864229e1dd7d30dd9e76dfefed604.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E6%9E%84%E5%BB%BAAgentHarness/images/972842/761864229e1dd7d30dd9e76dfefed604.jpg" alt=""></a></p>',56)])])}const c=l(r,[["render",o]]);export{u as __pageData,c as default};
